$ErrorActionPreference='Stop';$values=@{};Get-Content .env|ForEach-Object{if($_ -match '^([^#=]+)=(.*)$'){$values[$matches[1]]=$matches[2]}};$login=Invoke-RestMethod -Method Post -Uri 'http://localhost:20200/api/v1/auth/login' -ContentType 'application/json' -Body (@{email=$values.TEST_ACCOUNT_EMAIL;password=$values.TEST_ACCOUNT_PASSWORD}|ConvertTo-Json);$headers=@{Authorization="Bearer $($login.access_token)"}
function New-Session($title,$credits=500,$duration=3600){Invoke-RestMethod -Method Post -Uri 'http://localhost:20200/api/v1/sessions' -Headers $headers -ContentType 'application/json' -Body (@{title=$title;model='workama-chat';max_steps=10;max_credits=$credits;max_duration_seconds=$duration}|ConvertTo-Json)}
function Invoke-Agent($session,$mode){$ticket=Invoke-RestMethod -Method Post -Uri "http://localhost:20200/api/v1/sessions/$($session.id)/ws-tickets" -Headers $headers;$url="ws://localhost:20201/ws/sessions/$($session.id)?ticket=$([uri]::EscapeDataString($ticket.ticket))";$result=node tools/agent-native-smoke.mjs $url $mode|ConvertFrom-Json;if(-not $result.ok){throw "$mode runtime validation failed"};$result}
$native=Invoke-Agent (New-Session 'Native tool decision') 'native'
$creditsSession=New-Session 'Credit budget limit' 0.5 3600;$credits=Invoke-Agent $creditsSession 'credits'
$durationSession=New-Session 'Duration budget limit' 500 30;docker compose --env-file .env -f deploy/compose/docker-compose.yml exec -T postgres psql -v ON_ERROR_STOP=1 -U $values.POSTGRES_USER -d $values.POSTGRES_DB -c "UPDATE ag_session SET started_at=now()-interval '31 seconds' WHERE id='$($durationSession.id)'"|Out-Null;$duration=Invoke-Agent $durationSession 'duration'
$reconnectSession=New-Session 'Cross connection recovery';$reconnect=node tools/agent-reconnect-smoke.mjs $login.access_token $reconnectSession.id|ConvertFrom-Json;if(-not $reconnect.ok){throw 'Cross connection recovery failed'}
$evidence=[ordered]@{timestamp=[DateTimeOffset]::UtcNow.ToString('o');native_tool_call=$native.tool;native_final_response=$native.completed;usage_events=$native.usage_events;credit_limit_code=$credits.error;duration_limit_code=$duration.error;disconnect_run_survived=$reconnect.completed;cursor_replayed=$reconnect.replayed;new_connection_live_delivery=$reconnect.reconnected};$evidence|ConvertTo-Json|Set-Content quality/evidence/agent-runtime-limits-smoke.json;$evidence|ConvertTo-Json
